-- "🎁 Бонус всем": an admin of the club bot credits the same bonus to every
-- client who has a club card connected to the bot, with a message for them.
-- The bot sends the messages; this only credits and returns who to tell.

create table if not exists public.bonus_gifts (
  id uuid primary key default gen_random_uuid(),
  club_id uuid not null,
  -- generated by the bot at the preview step: a second tap on "confirm"
  -- finds it taken and credits nothing
  request_id uuid not null unique,
  amount bigint not null check (amount between 1 and 1000000),
  message text not null,
  created_by_tg bigint not null,
  recipients integer not null default 0,
  created_at timestamptz not null default now()
);
create index if not exists bonus_gifts_club_idx on public.bonus_gifts (club_id, created_at desc);

alter table public.bonus_gifts enable row level security;
drop policy if exists bonus_gifts_select on public.bonus_gifts;
create policy bonus_gifts_select on public.bonus_gifts
  for select using (app_is_club_member(club_id));

-- Clients the gift reaches: an active card linked to a Telegram account.
create or replace function public.bot_bonus_gift_count(p_club_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select count(*)::integer from customers
  where club_id = p_club_id and telegram_id is not null and active and archived_at is null;
$$;

create or replace function public.bot_bonus_gift(
  p_club_id uuid, p_admin_tg bigint, p_amount bigint, p_message text, p_request_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_gift_id uuid;
  v_rows jsonb;
  v_count integer;
begin
  if not exists (
    select 1 from club_bot_users
    where club_id = p_club_id and telegram_id = p_admin_tg and role = 'ADMIN'
  ) then
    return jsonb_build_object('ok', false, 'reason', 'NOT_ADMIN');
  end if;
  if p_amount is null or p_amount < 1 or p_amount > 1000000 then
    return jsonb_build_object('ok', false, 'reason', 'BAD_AMOUNT');
  end if;
  if coalesce(btrim(p_message), '') = '' or length(p_message) > 1000 then
    return jsonb_build_object('ok', false, 'reason', 'BAD_MESSAGE');
  end if;

  insert into bonus_gifts (club_id, request_id, amount, message, created_by_tg)
  values (p_club_id, p_request_id, p_amount, btrim(p_message), p_admin_tg)
  on conflict (request_id) do nothing
  returning id into v_gift_id;
  if v_gift_id is null then
    return jsonb_build_object('ok', false, 'reason', 'ALREADY_DONE');
  end if;

  with credited as (
    update customers c
    set bonus_points = c.bonus_points + p_amount
    where c.club_id = p_club_id and c.telegram_id is not null and c.active and c.archived_at is null
    returning c.id, c.telegram_id, c.bonus_points
  ), logged as (
    -- the client's history and the Mini App notifications read these
    insert into audit_logs (club_id, action, entity_type, entity_id, metadata)
    select p_club_id, 'customer.bonus_gift', 'customer', credited.id,
           jsonb_build_object('points', p_amount, 'gift_id', v_gift_id, 'message', btrim(p_message))
    from credited
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'telegram_id', credited.telegram_id,
           'bonus_points', credited.bonus_points,
           'lang', case when s.language = 'uz' then 'uz' else 'ru' end)), '[]'::jsonb),
         count(*)
    into v_rows, v_count
    from credited
    left join bot_state s on s.telegram_id = credited.telegram_id;

  update bonus_gifts set recipients = v_count where id = v_gift_id;

  return jsonb_build_object('ok', true, 'gift_id', v_gift_id, 'count', v_count, 'recipients', v_rows);
end;
$$;

-- Only the bot (service role) may call these.
revoke all on function public.bot_bonus_gift_count(uuid) from public, anon, authenticated;
revoke all on function public.bot_bonus_gift(uuid, bigint, bigint, text, uuid) from public, anon, authenticated;
grant execute on function public.bot_bonus_gift_count(uuid) to service_role;
grant execute on function public.bot_bonus_gift(uuid, bigint, bigint, text, uuid) to service_role;
